    bool canReach(const vector<vector<pair<int, int>>>& graph, const vector<bool>& online, long long k, int limit, int n) {
        vector<long long> dist(n, LLONG_MAX);
        dist[0] = 0;

        vector<int> indegree(n, 0);

        for (int u = 0; u < n; u++) {
            if (u != 0 && u != n - 1 && !online[u]) continue;

